// 0.70.2 sMe binds each card's subagentId to scoped actions; see the evidence doc.
// The 0.18 overlay is selection-based, so wait for the explicit transcript owner.
export function RConversationComputerCardActions(runtime, agentId, card, openComputer) {
  const target = card.subagentId ?? agentId;
  const valid = typeof agentId === 'string' && agentId.length > 0 &&
    typeof target === 'string' && target.length > 0;
  const resolve = async reason => {
    if (!valid || card.status !== 'waiting') return false;
    const handoff = runtime.foreverBox.getStatus(target)?.handoff;
    if (handoff?.requestId !== card.requestId) return false;
    await runtime.foreverBox.handBack(target, reason);
    return true;
  };
  return {
    card,
    async openBox() {
      if (!valid) return;
      runtime.selection.select(agentId);
      await runtime.selection.waitForReady(agentId);
      if (runtime.selection.readCurrentAgentId() !== agentId) return;
      openComputer(card.subagentId ?? undefined);
      runtime.foreverBox.ensure(target);
    },
    handBack: () => resolve('button'),
    dismiss: () => resolve('dismissed'),
  };
}

const HOOK = `function Dbn(n,e,entry){
const agentId=Mee(),runtime=Qe(),owner=entry?.boxRequestId!=null?agentId:null;
const base=NTn(owner),monitors=MTn(owner);
return S.useMemo(()=>{
 if(owner==null||entry?.boxRequestId==null)return null;
 const handoffs=monitors.filter(m=>m.handoff!=null).map(m=>({...m.handoff,subagentId:m.subagentId}));
 if(base.handoff!=null)handoffs.push({...base.handoff,subagentId:null});
 const card=entry.boxResolution!=null?Obn([],[entry]).get(n):e??Obn(handoffs,[entry]).get(n);
 if(card==null)return null;
 const actions=RConversationComputerCardActions(runtime,owner,card,id=>Dzn.openComputer(id));
 return{card:{...card,agentId:owner,reason:entry.boxReason},openBox:()=>actions.openBox().catch(ETn),handBack:actions.handBack,dismiss:actions.dismiss};
},[n,e,entry,owner,runtime,base.handoff,monitors]);
}`;

// Local feedback mirrors official localHandoffResolution/handBackAttempt. Keying the
// component by owner + monitor + request discards late feedback after navigation.
export function RConversationCardInteraction(props) {
  const [attempt, setAttempt] = S.useState({ kind: 'idle' });
  const [resolution, setResolution] = S.useState(null);
  const pending = S.useRef(false);
  const resolve = async (action, status) => {
    if (pending.current || resolution != null || props.status !== 'waiting') return;
    pending.current = true;
    setAttempt({ kind: 'pending' });
    try {
      const accepted = await action();
      if (accepted !== false) setResolution(status);
      setAttempt({ kind: 'idle' });
    } catch {
      setAttempt({ kind: 'failed' });
    } finally {
      pending.current = false;
    }
  };
  return p.jsx(RConversationOfficialCard, {
    instruction: props.instruction,
    status: props.status === 'waiting' ? resolution ?? props.status : props.status,
    reason: props.reason,
    screen: { agentId: props.subagentId ?? props.agentId, dataUrl: props.snapshotDataUrl },
    surface: props.surface ?? 'elevated',
    handBackAttempt: attempt,
    onOpen: props.onOpen,
    onHandBack: () => resolve(props.onHandBack, 'handed_back'),
    onDismiss: () => resolve(props.onDismiss, 'dismissed'),
  });
}

const CARD_WRAPPER = `function Hbn(props){return p.jsx("div",{className:"r-conversation-computer-card",children:p.jsx(RConversationCardInteraction,{...props},JSON.stringify([props.agentId,props.subagentId,props.requestId]))})}`;

function unique(source, anchor) {
  const start = source.indexOf(anchor);
  if (start < 0 || source.indexOf(anchor, start + anchor.length) >= 0) {
    throw new Error(`Conversation computer card anchor missing or ambiguous: ${anchor}`);
  }
  return start;
}

export function patchConversationComputerCard(source) {
  const start = unique(source, 'function Dbn(n,e){');
  const end = unique(source, 'function Rbn(){}function Fbn(){}function zbn(){}');
  if (end <= start) throw new Error('Conversation computer card hook boundaries moved');
  const original = source.slice(start, end);
  for (const anchor of ['openBox:zbn,handBack:Fbn,dismiss:Rbn', 'Yte.openBox(r.subagentId)', 'Yte.handBack(r.subagentId)', 'Yte.dismiss(r.subagentId)']) unique(original, anchor);
  unique(source, 'const u=Dbn(o,c);');
  unique(source, 'function Hbn(n){');
  unique(source, 'e[5]!==v.instruction');
  unique(source, 'e[5]=v.instruction');
  unique(source, 'p.jsx(Hbn,{instruction:v.instruction,');
  const frame = 'className:"sand-box-handoff-card-wrap",isGroupStart:s.isGroupStart,timestampMs:t.timestampMs,variant:"tab"';
  unique(source, frame);
  // These must remain real upstream primitives, not guessed renderer globals.
  for (const anchor of ['function Mee()', 'function NTn(n)', 'function MTn(n)', 'function Obn(n,e)', 'function ETn(', 'openComputer:n=>GD.open(Uf.computer(']) unique(source, anchor);
  const view = RConversationOfficialCardFactory.toString() +
    '\nconst RConversationOfficialCard=RConversationOfficialCardFactory(S,he,p,Fe,re,bt,RLocT);\n' +
    RConversationCardInteraction.toString() + CARD_WRAPPER;
  return (source.slice(0, start) + RConversationComputerCardActions.toString() + HOOK + source.slice(end))
    .replace('const u=Dbn(o,c);', 'const u=Dbn(o,c,t);')
    .replace('function Hbn(n){', view + 'function RConversationLegacyCard(n){')
    .replace('e[5]!==v.instruction', 'e[5]!==v')
    .replace('e[5]=v.instruction', 'e[5]=v')
    .replace(frame, frame.replace('variant:"tab"', 'variant:"question"'))
    .replace('p.jsx(Hbn,{instruction:v.instruction,', 'p.jsx(Hbn,{agentId:v.agentId,subagentId:v.subagentId,requestId:v.requestId,reason:v.reason,instruction:v.instruction,');
}

export async function applyOriginalRendererConversationComputerCard({ appRoot }) {
  const relative = 'dist/renderer/assets/index-UbX-y3il.js';
  const file = path.join(appRoot, relative);
  const source = await readFile(file, 'utf8');
  const patched = patchConversationComputerCard(source);
  const assets = path.dirname(file);
  const cssFiles = (await readdir(assets)).filter(name => /^index-.*\.css$/.test(name));
  if (cssFiles.length !== 1) throw new Error('Conversation card requires exactly one main stylesheet');
  const cssPath = path.join(assets, cssFiles[0]);
  const css = await readFile(cssPath, 'utf8');
  if (css.includes('.r-conversation-computer-card')) throw new Error('Conversation card CSS already applied');
  const patchedCss = css + '\n' + CONVERSATION_COMPUTER_CARD_CSS;
  const sha256 = value => createHash('sha256').update(value).digest('hex');
  const evidence = { version: 2, file: relative, originalSha256: sha256(source), patchedSha256: sha256(patched), referenceVersion: '0.70.2', css: { file: 'dist/renderer/assets/' + cssFiles[0], originalSha256: sha256(css), patchedSha256: sha256(patchedCss) } };
  await writeFile(file, patched);
  await writeFile(cssPath, patchedCss);
  await writeFile(path.join(appRoot, 'dist/renderer-conversation-computer-card-extension.json'), JSON.stringify(evidence, null, 2) + '\n');
  return evidence;
}

